  private def why(r: Row, outcome: Either[String, (Json, Long)]): String = {
    import AvlDigestText._
    val base = r.kind match {
      case "read" => Read; case "hand" => Hand; case "flag" => Flag; case "write" => Write
      case "eq" => Eq; case "subst" => Subst; case "lift" => Lift
    }
    val role =
      if (r.control) "CONTROL: a byte digest, as an implementation that requires one expects."
      else outcome match {
        case Right(_) if r.kind == "write" => "SEPARATING on cost: a writer that charges 33 bytes for any digest."
        case Right(_) => "SEPARATING: an implementation that refuses a non-byte or other-length digest at updateDigest " +
          "(or that reads it here) errors."
        case Left(_) if r.kind == "lift" => "SEPARATING: an implementation that lifts this kind returns the script."
        case Left(_) => "SEPARATING: an implementation that accepts it returns a value."
      }
    s"$base $role"
  }

  def extract(): Map[String, Json] =
    Ops.map { op =>
      val entries = Rows.filter(_.op == op).zipWithIndex.map { case (r, i) =>
        val (_, outcome) = EvalCore.evalApplied(r.treeHex, IntInput, activated = r.activated)
        val said = outcome.fold(e => s"— THROWS (`${e.take(100)}`)", { case (v, c) =>
          val vs = v.hcursor.downField("value").focus.orElse(v.hcursor.downField("items").focus).map(_.noSpaces)
            .getOrElse(v.noSpaces)
          s"→ ${if (vs.length > 80) vs.take(77) + "…" else vs} at cost $c" })
        val s = s"[${r.id}] ${r.expr} $said. ${why(r, outcome)}"
        val name = s"${r.id.replace('|', '-').replaceAll("[\\[\\],]", "")}#$i"
        if (r.accept) SpecExtract.authoredEntryV(op, s, r.treeHex, name, IntInput, r.activated, ergoTree = r.ergoTree)
        else SpecExtract.authoredRejectEntryV(op, s, r.treeHex, name, IntInput, r.activated, ergoTree = r.ergoTree)
      }
      op -> SpecExtract.authoredEnvelope(op, entries, Source).mapObject(_.add("blessed_by", Json.fromString(Stamp)))
    }.toMap

  def writeVectors(outDir: java.nio.file.Path): Unit =
    SpecExtract.writeStaging("AuthoredEvalAvlDigestCollection", extract(), outDir)
}
